ALTER TABLE hr_person_profile ADD COLUMN IF NOT EXISTS position_number VARCHAR(32) NULL, ADD COLUMN IF NOT EXISTS salary DECIMAL(10,2) NULL, ADD COLUMN IF NOT EXISTS parent_agency VARCHAR(255) NULL, ADD COLUMN IF NOT EXISTS gpf_status VARCHAR(16) NULL, ADD COLUMN IF NOT EXISTS first_appointed_on DATE NULL, ADD COLUMN IF NOT EXISTS reappointed_on DATE NULL, ADD COLUMN IF NOT EXISTS transferred_in_on DATE NULL, ADD COLUMN IF NOT EXISTS transferred_out_on DATE NULL, ADD COLUMN IF NOT EXISTS joined_unit_on DATE NULL, ADD COLUMN IF NOT EXISTS current_level_since DATE NULL, ADD COLUMN IF NOT EXISTS qualification VARCHAR(255) NULL, ADD COLUMN IF NOT EXISTS qualification_major VARCHAR(255) NULL, ADD COLUMN IF NOT EXISTS special_allowance VARCHAR(255) NULL;
CREATE TABLE IF NOT EXISTS hr_person_education (id CHAR(36) PRIMARY KEY, person_id CHAR(36) NOT NULL, sequence SMALLINT NOT NULL, graduated_on DATE NULL, degree VARCHAR(255) NOT NULL, major VARCHAR(255) NULL, institution VARCHAR(255) NULL, country VARCHAR(120) NULL, created_at DATETIME NOT NULL, CONSTRAINT hr_person_education_person_fk FOREIGN KEY (person_id) REFERENCES person(id), UNIQUE KEY hr_person_education_order (person_id, sequence));
